1	import { getAuthorization, handleExpiredRequest } from '@/service/request/shared';
2	import type { RequestInstanceState } from '@/service/request/type';
3	
4	const fetchState: RequestInstanceState = {
5	  refreshTokenFn: null,
6	  errMsgStack: []
7	};
8	
9	function getExpiredTokenCodes() {
10	  return import.meta.env.VITE_SERVICE_EXPIRED_TOKEN_CODES?.split(',') || [];
11	}
12	
13	function buildHeaders(headersInit?: HeadersInit) {
14	  const headers = new Headers(headersInit);
15	  const authorization = getAuthorization();
16	
17	  if (authorization) {
18	    headers.set('Authorization', authorization);
19	  }
20	
21	  return headers;
22	}
23	
24	async function isExpiredResponse(response: Response) {
25	  if (response.status === 401) {
26	    return true;
27	  }
28	
29	  const contentType = response.headers.get('content-type') || '';
30	  if (!contentType.includes('application/json')) {
31	    return false;
32	  }
33	
34	  try {
35	    const payload = await response.clone().json();
36	    const code = String(payload?.code || '');
37	    return getExpiredTokenCodes().includes(code);
38	  } catch {
39	    return false;
40	  }
41	}
42	
43	export async function authFetch(input: RequestInfo | URL, init: RequestInit = {}) {
44	  const requestInit: RequestInit = {
45	    ...init,
46	    headers: buildHeaders(init.headers)
47	  };
48	
49	  let response = await fetch(input, requestInit);
50	
51	  if (await isExpiredResponse(response)) {
52	    const refreshed = await handleExpiredRequest(fetchState);
53	    if (refreshed) {
54	      response = await fetch(input, {
55	        ...init,
56	        headers: buildHeaders(init.headers)
57	      });
58	    }
59	  }
60	
61	  return response;
62	}
