1	import type { AxiosResponse } from 'axios';
2	import { BACKEND_ERROR_CODE, createFlatRequest, createRequest } from '@sa/axios';
3	import { useAuthStore } from '@/store/modules/auth';
4	import { localStg } from '@/utils/storage';
5	import { getServiceBaseURL } from '@/utils/service';
6	import { $t } from '@/locales';
7	import { getAuthorization, handleExpiredRequest, showErrorMsg } from './shared';
8	import type { RequestInstanceState } from './type';
9	
10	const isHttpProxy = import.meta.env.DEV && import.meta.env.VITE_HTTP_PROXY === 'Y';
11	const { baseURL, otherBaseURL } = getServiceBaseURL(import.meta.env, isHttpProxy);
12	
13	export const request = createFlatRequest<App.Service.Response, RequestInstanceState>(
14	  {
15	    baseURL,
16	    headers: {
17	      apifoxToken: 'XL299LiMEDZ0H5h3A29PxwQXdMJqWyY2'
18	    }
19	  },
20	  {
21	    async onRequest(config) {
22	      const Authorization = getAuthorization();
23	      Object.assign(config.headers, { Authorization });
24	
25	      return config;
26	    },
27	    isBackendSuccess(response) {
28	      // when the backend response code is "0000"(default), it means the request is success
29	      // to change this logic by yourself, you can modify the `VITE_SERVICE_SUCCESS_CODE` in `.env` file
30	      return String(response.data.code) === import.meta.env.VITE_SERVICE_SUCCESS_CODE;
31	    },
32	    async onBackendFail(response, instance) {
33	      const authStore = useAuthStore();
34	      const responseCode = String(response.data.code);
35	
36	      function handleLogout() {
37	        authStore.resetStore();
38	      }
39	
40	      function logoutAndCleanup() {
41	        handleLogout();
42	        window.removeEventListener('beforeunload', handleLogout);
43	
44	        request.state.errMsgStack = request.state.errMsgStack.filter(msg => msg !== response.data.msg);
45	      }
46	
47	      // when the backend response code is in `logoutCodes`, it means the user will be logged out and redirected to login page
48	      const logoutCodes = import.meta.env.VITE_SERVICE_LOGOUT_CODES?.split(',') || [];
49	      if (logoutCodes.includes(responseCode)) {
50	        handleLogout();
51	        return null;
52	      }
53	
54	      // when the backend response code is in `modalLogoutCodes`, it means the user will be logged out by displaying a modal
55	      const modalLogoutCodes = import.meta.env.VITE_SERVICE_MODAL_LOGOUT_CODES?.split(',') || [];
56	      if (modalLogoutCodes.includes(responseCode) && !request.state.errMsgStack?.includes(response.data.msg)) {
57	        request.state.errMsgStack = [...(request.state.errMsgStack || []), response.data.msg];
58	
59	        // prevent the user from refreshing the page
60	        window.addEventListener('beforeunload', handleLogout);
61	
62	        window.$dialog?.error({
63	          title: $t('common.error'),
64	          content: response.data.msg,
65	          positiveText: $t('common.confirm'),
66	          maskClosable: false,
67	          closeOnEsc: false,
68	          onPositiveClick() {
69	            logoutAndCleanup();
70	          },
71	          onClose() {
72	            logoutAndCleanup();
73	          }
74	        });
75	
76	        return null;
77	      }
78	
79	      // when the backend response code is in `expiredTokenCodes`, it means the token is expired, and refresh token
80	      // the api `refreshToken` can not return error code in `expiredTokenCodes`, otherwise it will be a dead loop, should return `logoutCodes` or `modalLogoutCodes`
81	      const expiredTokenCodes = import.meta.env.VITE_SERVICE_EXPIRED_TOKEN_CODES?.split(',') || [];
82	      if (expiredTokenCodes.includes(responseCode)) {
83	        const success = await handleExpiredRequest(request.state);
84	        if (success) {
85	          const Authorization = getAuthorization();
86	          Object.assign(response.config.headers, { Authorization });
87	
88	          return instance.request(response.config) as Promise<AxiosResponse>;
89	        }
90	      }
91	
92	      return null;
93	    },
94	    transformBackendResponse(response) {
95	      return response.data.data;
96	    },
97	    onError(error) {
98	      // when the request is fail, you can show error message
99	
100	      let message = error.message;
101	      let backendErrorCode = '';
102	
103	      // get backend error message and code
104	      if (error.code === BACKEND_ERROR_CODE) {
105	        message = error.response?.data?.msg || message;
106	        backendErrorCode = String(error.response?.data?.code || '');
107	      }
108	
109	      // the error message is displayed in the modal
110	      const modalLogoutCodes = import.meta.env.VITE_SERVICE_MODAL_LOGOUT_CODES?.split(',') || [];
111	      if (modalLogoutCodes.includes(backendErrorCode)) {
112	        return;
113	      }
114	
115	      // when the token is expired, refresh token and retry request, so no need to show error message
116	      const expiredTokenCodes = import.meta.env.VITE_SERVICE_EXPIRED_TOKEN_CODES?.split(',') || [];
117	      if (expiredTokenCodes.includes(backendErrorCode)) {
118	        return;
119	      }
120	
121	      showErrorMsg(request.state, message);
122	    }
123	  }
124	);
125	
126	export const demoRequest = createRequest<App.Service.DemoResponse>(
127	  {
128	    baseURL: otherBaseURL.demo
129	  },
130	  {
131	    async onRequest(config) {
132	      const { headers } = config;
133	
134	      // set token
135	      const token = localStg.get('token');
136	      const Authorization = token ? `Bearer ${token}` : null;
137	      Object.assign(headers, { Authorization });
138	
139	      return config;
140	    },
141	    isBackendSuccess(response) {
142	      // when the backend response code is "200", it means the request is success
143	      // you can change this logic by yourself
144	      return response.data.status === '200';
145	    },
146	    async onBackendFail(_response) {
147	      // when the backend response code is not "200", it means the request is fail
148	      // for example: the token is expired, refresh token and retry request
149	    },
150	    transformBackendResponse(response) {
151	      return response.data.result;
152	    },
153	    onError(error) {
154	      // when the request is fail, you can show error message
155	
156	      let message = error.message;
157	
158	      // show backend error message
159	      if (error.code === BACKEND_ERROR_CODE) {
160	        message = error.response?.data?.message || message;
161	      }
162	
163	      window.$message?.error(message);
164	    }
165	  }
166	);
