1	import { computed, reactive, ref } from 'vue';
2	import { useRoute } from 'vue-router';
3	import { defineStore } from 'pinia';
4	import { useLoading } from '@sa/hooks';
5	import { fetchGetUserInfo, fetchLogin } from '@/service/api';
6	import { useRouterPush } from '@/hooks/common/router';
7	import { localStg } from '@/utils/storage';
8	import { SetupStoreId } from '@/enum';
9	import { $t } from '@/locales';
10	import { useRouteStore } from '../route';
11	import { useTabStore } from '../tab';
12	import { clearAuthStorage, getToken } from './shared';
13	
14	export const useAuthStore = defineStore(SetupStoreId.Auth, () => {
15	  const route = useRoute();
16	  const authStore = useAuthStore();
17	  const routeStore = useRouteStore();
18	  const tabStore = useTabStore();
19	  const { toLogin, redirectFromLogin } = useRouterPush(false);
20	  const { loading: loginLoading, startLoading, endLoading } = useLoading();
21	
22	  const token = ref(getToken());
23	
24	  const userInfo: Api.Auth.UserInfo = reactive({
25	    userId: '',
26	    userName: '',
27	    roles: [],
28	    buttons: []
29	  });
30	
31	  /** is super role in static route */
32	  const isStaticSuper = computed(() => {
33	    const { VITE_AUTH_ROUTE_MODE, VITE_STATIC_SUPER_ROLE } = import.meta.env;
34	
35	    return VITE_AUTH_ROUTE_MODE === 'static' && userInfo.roles.includes(VITE_STATIC_SUPER_ROLE);
36	  });
37	
38	  /** Is login */
39	  const isLogin = computed(() => Boolean(token.value));
40	
41	  /** Reset auth store */
42	  async function resetStore() {
43	    recordUserId();
44	
45	    clearAuthStorage();
46	
47	    authStore.$reset();
48	
49	    if (!route.meta.constant) {
50	      await toLogin();
51	    }
52	
53	    tabStore.cacheTabs();
54	    routeStore.resetStore();
55	  }
56	
57	  /** Record the user ID of the previous login session Used to compare with the current user ID on next login */
58	  function recordUserId() {
59	    if (!userInfo.userId) {
60	      return;
61	    }
62	
63	    // Store current user ID locally for next login comparison
64	    localStg.set('lastLoginUserId', userInfo.userId);
65	  }
66	
67	  /**
68	   * Check if current login user is different from previous login user If different, clear all tabs
69	   *
70	   * @returns {boolean} Whether to clear all tabs
71	   */
72	  function checkTabClear(): boolean {
73	    if (!userInfo.userId) {
74	      return false;
75	    }
76	
77	    const lastLoginUserId = localStg.get('lastLoginUserId');
78	
79	    // Clear all tabs if current user is different from previous user
80	    if (!lastLoginUserId || lastLoginUserId !== userInfo.userId) {
81	      localStg.remove('globalTabs');
82	      tabStore.clearTabs();
83	
84	      localStg.remove('lastLoginUserId');
85	      return true;
86	    }
87	
88	    localStg.remove('lastLoginUserId');
89	    return false;
90	  }
91	
92	  /**
93	   * Login
94	   *
95	   * @param userName User name
96	   * @param password Password
97	   * @param [redirect=true] Whether to redirect after login. Default is `true`
98	   */
99	  async function login(userName: string, password: string, redirect = true) {
100	    startLoading();
101	
102	    const { data: loginToken, error } = await fetchLogin(userName, password);
103	
104	    if (!error) {
105	      const pass = await loginByToken(loginToken);
106	
107	      if (pass) {
108	        // Check if the tab needs to be cleared
109	        const isClear = checkTabClear();
110	        let needRedirect = redirect;
111	
112	        if (isClear) {
113	          // If the tab needs to be cleared,it means we don't need to redirect.
114	          needRedirect = false;
115	        }
116	        await redirectFromLogin(needRedirect);
117	
118	        window.$notification?.success({
119	          title: $t('page.login.common.loginSuccess'),
120	          content: $t('page.login.common.welcomeBack', { userName: userInfo.userName }),
121	          duration: 4500
122	        });
123	      }
124	    } else {
125	      resetStore();
126	    }
127	
128	    endLoading();
129	  }
130	
131	  async function loginByToken(loginToken: Api.Auth.LoginToken) {
132	    // 1. stored in the localStorage, the later requests need it in headers
133	    localStg.set('token', loginToken.token);
